/**
 * bf-concept-graph.canvas.tsx — interactive directed graph of Benefuture (Bf)
 * concepts, parsed from Bf_Pseudocode.txt.
 *
 * GENERATED FILE — do not edit by hand. The GENERATED data block below is
 * rewritten by tools/bf-graph/build-graph.mjs whenever the pseudocode changes.
 * To change the UI, edit tools/bf-graph/canvas-template.tsx and re-run
 *   npm run graph:build
 * then reload the canvas tab. (npm run graph:watch rebuilds on every save.)
 */
import {
  Button,
  Card,
  CardBody,
  CardHeader,
  computeDAGLayout,
  H1,
  Pill,
  Row,
  Select,
  Stack,
  Stat,
  Text,
  TextInput,
  useCanvasAction,
  useCanvasState,
  useEffect,
  useHostTheme,
  useMemo,
  useRef,
  useState,
} from "cursor/canvas";
import type { DAGLayoutEdge } from "cursor/canvas";

type GeneratedNode = {
  id: string;
  name: string;
  cat: string;
  def: string;
  line: number | null;
  subGoal: boolean;
  axiom: boolean;
  isSet: boolean;
};
type GeneratedEdge = { from: string; to: string; kind: string };
type GeneratedCategory = { id: string; label: string; color: string; count: number };
type GeneratedData = {
  source: string;
  sourcePath: string;
  generatedAt: string;
  stats: { sections: number; axioms: number };
  categories: GeneratedCategory[];
  nodes: GeneratedNode[];
  edges: GeneratedEdge[];
};

// __GENERATED_DATA_BEGIN__
// Auto-generated by tools/bf-graph/build-graph.mjs — do not edit by hand.
const GENERATED: GeneratedData = { source: "", sourcePath: "", generatedAt: "", stats: { sections: 0, axioms: 0 }, categories: [], nodes: [], edges: [] };
// __GENERATED_DATA_END__

const NODE_W = 156;
const NODE_H = 48;

const trunc = (s: string, n: number) => (s.length > n ? s.slice(0, n - 1) + "…" : s);
const edgeKey = (from: string, to: string) => from + "→" + to;

export default function BfConceptGraph() {
  const theme = useHostTheme();
  const dispatch = useCanvasAction();

  const [direction, setDirection] = useCanvasState<"horizontal" | "vertical" | "free">("bf-graph-direction", "horizontal");
  const [hiddenCats, setHiddenCats] = useCanvasState<string[]>("bf-graph-hidden-cats", []);
  const [query, setQuery] = useState("");
  const [transform, setTransform] = useState({ x: 24, y: 24, k: 0.7 });

  const nodeById = useMemo(() => new Map(GENERATED.nodes.map((n) => [n.id, n])), []);
  const catById = useMemo(() => new Map(GENERATED.categories.map((c) => [c.id, c])), []);

  const hubId = useMemo(() => {
    const deg = new Map<string, number>();
    for (const e of GENERATED.edges) {
      deg.set(e.from, (deg.get(e.from) ?? 0) + 1);
      deg.set(e.to, (deg.get(e.to) ?? 0) + 1);
    }
    let best: string | null = null;
    let bestDeg = -1;
    for (const [id, d] of deg) {
      if (d > bestDeg) {
        best = id;
        bestDeg = d;
      }
    }
    return best;
  }, []);

  const [selected, setSelected] = useState<string | null>(hubId);
  const [hovered, setHovered] = useState<string | null>(null);

  const containerRef = useRef<HTMLDivElement | null>(null);
  const svgRef = useRef<SVGSVGElement | null>(null);
  const dragRef = useRef<{ px: number; py: number; x: number; y: number; moved: boolean } | null>(null);
  const nodeDragRef = useRef<{ id: string; dx: number; dy: number; gx: number; gy: number; moved: boolean } | null>(null);
  const lastDragMoved = useRef(false);

  const rootRef = useRef<HTMLDivElement | null>(null);
  const [pageWidth, setPageWidth] = useState(0);

  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const update = () => setPageWidth(el.getBoundingClientRect().width);
    update();
    if (typeof ResizeObserver !== "undefined") {
      const ro = new ResizeObserver(update);
      ro.observe(el);
      return () => ro.disconnect();
    }
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);

  const isNarrow = pageWidth > 0 && pageWidth < 780;

  const catColor = (catId: string): string => {
    const meta = catById.get(catId);
    const palette = theme.category as Record<string, string>;
    return (meta && palette[meta.color]) || theme.text.tertiary;
  };

  // ---- filtering -------------------------------------------------------------
  const visibleNodes = useMemo(
    () => GENERATED.nodes.filter((n) => !hiddenCats.includes(n.cat)),
    [hiddenCats]
  );
  const visibleIds = useMemo(() => new Set(visibleNodes.map((n) => n.id)), [visibleNodes]);
  const visibleEdges = useMemo(
    () => GENERATED.edges.filter((e) => visibleIds.has(e.from) && visibleIds.has(e.to)),
    [visibleIds]
  );

  const q = query.trim().toLowerCase();
  const matchIds = useMemo(() => {
    if (!q) return null;
    return new Set(
      GENERATED.nodes
        .filter((n) => n.id.toLowerCase().includes(q) || n.name.toLowerCase().includes(q))
        .map((n) => n.id)
    );
  }, [q]);

  // ---- layout ------------------------------------------------------------------
  const isFree = direction === "free";
  const layout = useMemo(
    () =>
      computeDAGLayout({
        nodes: visibleNodes.map((n) => ({ id: n.id })),
        edges: visibleEdges.map((e) => ({ from: e.from, to: e.to })),
        direction: direction === "free" ? "horizontal" : direction,
        nodeWidth: NODE_W,
        nodeHeight: NODE_H,
        rankGap: 72,
        nodeGap: 16,
        padding: 20,
      }),
    [visibleNodes, visibleEdges, direction]
  );
  const posById = useMemo(() => new Map(layout.nodes.map((n) => [n.id, n])), [layout]);

  // ---- free-floating layout (force-directed, draggable) -------------------------
  const nodeW = (id: string) => {
    if (!isFree) return NODE_W;
    const n = nodeById.get(id);
    const label = n ? n.name : id;
    return Math.max(64, Math.ceil(label.length * 6.6) + 22);
  };
  const nodeH = (_id: string) => (isFree ? 40 : NODE_H);

  // Live force simulation: nodes auto-arrange from a spiral seed, then cool and
  // settle. Dragging a node pins it and reheats the sim so neighbors re-settle.
  const [freePos, setFreePos] = useState<Map<string, { x: number; y: number }> | null>(null);
  const simRef = useRef<{ pos: Map<string, { x: number; y: number }>; temp: number; raf: number | null; settled: boolean } | null>(null);
  const fitViewRef = useRef<(() => void) | null>(null);

  const stepSim = () => {
    const sim = simRef.current;
    if (!sim) return;
    const pos = sim.pos;
    const ids = [...pos.keys()];
    if (ids.length === 0) return;
    const disp = new Map<string, { x: number; y: number }>(ids.map((id) => [id, { x: 0, y: 0 }]));
    for (let i = 0; i < ids.length; i++) {
      const a = pos.get(ids[i])!;
      const da = disp.get(ids[i])!;
      for (let j = i + 1; j < ids.length; j++) {
        const b = pos.get(ids[j])!;
        const db = disp.get(ids[j])!;
        let dx = a.x - b.x;
        let dy = a.y - b.y;
        let d2 = dx * dx + dy * dy;
        if (d2 < 0.01) {
          dx = 0.13 * (i - j || 1);
          dy = 0.07;
          d2 = dx * dx + dy * dy;
        }
        const d = Math.sqrt(d2);
        const f = 45000 / d2;
        const ux = dx / d;
        const uy = dy / d;
        da.x += ux * f;
        da.y += uy * f;
        db.x -= ux * f;
        db.y -= uy * f;
      }
    }
    for (const e of visibleEdges) {
      const a = pos.get(e.from);
      const b = pos.get(e.to);
      if (!a || !b) continue;
      const da = disp.get(e.from)!;
      const db = disp.get(e.to)!;
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const d = Math.max(1, Math.hypot(dx, dy));
      const f = (d - 200) * 0.04;
      const ux = dx / d;
      const uy = dy / d;
      da.x += ux * f;
      da.y += uy * f;
      db.x -= ux * f;
      db.y -= uy * f;
    }
    let cx = 0;
    let cy = 0;
    for (const id of ids) {
      const p = pos.get(id)!;
      cx += p.x;
      cy += p.y;
    }
    cx /= ids.length;
    cy /= ids.length;
    const maxStep = 26 * sim.temp;
    for (const id of ids) {
      if (nodeDragRef.current?.id === id) continue;
      const p = pos.get(id)!;
      const d = disp.get(id)!;
      d.x += (cx - p.x) * 0.012;
      d.y += (cy - p.y) * 0.012;
      const len = Math.hypot(d.x, d.y) || 1;
      const s = Math.min(len, maxStep) / len;
      p.x += d.x * s;
      p.y += d.y * s;
    }
    for (let i = 0; i < ids.length; i++) {
      for (let j = i + 1; j < ids.length; j++) {
        const a = pos.get(ids[i])!;
        const b = pos.get(ids[j])!;
        const aw = nodeW(ids[i]);
        const bw = nodeW(ids[j]);
        const ox = Math.min(a.x + aw + 14, b.x + bw + 14) - Math.max(a.x - 14, b.x - 14);
        const oy = Math.min(a.y + 54, b.y + 54) - Math.max(a.y - 14, b.y - 14);
        if (ox > 0 && oy > 0) {
          if (ox < oy) {
            if (a.x < b.x) { a.x -= ox / 2; b.x += ox / 2; } else { a.x += ox / 2; b.x -= ox / 2; }
          } else {
            if (a.y < b.y) { a.y -= oy / 2; b.y += oy / 2; } else { a.y += oy / 2; b.y -= oy / 2; }
          }
        }
      }
    }
    const nd = nodeDragRef.current;
    if (nd && pos.has(nd.id)) {
      pos.set(nd.id, { x: nd.gx - nd.dx, y: nd.gy - nd.dy });
    }
    sim.temp = Math.max(0, sim.temp * 0.98 - 0.0002);
  };

  const ensureSimRunning = () => {
    const sim = simRef.current;
    if (!sim || sim.raf != null) return;
    const tick = () => {
      const s = simRef.current;
      if (!s) return;
      stepSim();
      setFreePos(new Map(s.pos));
      if (s.temp > 0.02 || nodeDragRef.current) {
        s.raf = requestAnimationFrame(tick);
      } else {
        s.raf = null;
        if (!s.settled) {
          s.settled = true;
          fitViewRef.current?.();
        }
      }
    };
    sim.raf = requestAnimationFrame(tick);
  };

  const reheat = (t: number) => {
    const sim = simRef.current;
    if (!sim) return;
    sim.temp = Math.max(sim.temp, t);
    sim.settled = false;
    ensureSimRunning();
  };

  useEffect(() => {
    if (!isFree) {
      const sim = simRef.current;
      if (sim && sim.raf != null) cancelAnimationFrame(sim.raf);
      simRef.current = null;
      setFreePos(null);
      return;
    }
    const pos = new Map<string, { x: number; y: number }>();
    visibleNodes.forEach((n, i) => {
      const r = 120 * Math.sqrt(i + 0.5);
      const a = i * 2.399963;
      pos.set(n.id, { x: 700 + r * Math.cos(a), y: 500 + r * Math.sin(a) });
    });
    const prev = simRef.current;
    if (prev && prev.raf != null) cancelAnimationFrame(prev.raf);
    simRef.current = { pos, temp: 1, raf: null, settled: false };
    setFreePos(new Map(pos));
    ensureSimRunning();
    requestAnimationFrame(() => fitViewRef.current?.());
    return () => {
      const sim = simRef.current;
      if (sim && sim.raf != null) cancelAnimationFrame(sim.raf);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isFree, visibleNodes, visibleEdges]);

  const posOf = (id: string): { x: number; y: number } | null => {
    if (isFree) return freePos?.get(id) ?? null;
    const p = posById.get(id);
    return p ? { x: p.x, y: p.y } : null;
  };

  const graphSize = useMemo(() => {
    if (!isFree) return { w: layout.width, h: layout.height };
    if (!freePos || freePos.size === 0) return { w: 0, h: 0 };
    let maxX = 0;
    let maxY = 0;
    for (const [id, p] of freePos) {
      maxX = Math.max(maxX, p.x + nodeW(id));
      maxY = Math.max(maxY, p.y + 40);
    }
    return { w: maxX + 28, h: maxY + 28 };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isFree, layout, freePos]);

  // ---- selection neighborhood ----------------------------------------------------
  const selectedNode = selected ? nodeById.get(selected) ?? null : null;
  const neighborInfo = useMemo(() => {
    if (!selected) return null;
    const dependsOn: string[] = [];
    const feedsInto: string[] = [];
    for (const e of visibleEdges) {
      if (e.to === selected) dependsOn.push(e.from);
      if (e.from === selected) feedsInto.push(e.to);
    }
    return { dependsOn, feedsInto, set: new Set([selected, ...dependsOn, ...feedsInto]) };
  }, [selected, visibleEdges]);

  useEffect(() => {
    if (selected && !visibleIds.has(selected)) setSelected(null);
  }, [visibleIds, selected]);

  // ---- pan / zoom ------------------------------------------------------------------
  const fitView = () => {
    const el = containerRef.current;
    if (!el || graphSize.w === 0 || graphSize.h === 0) return;
    const rect = el.getBoundingClientRect();
    const k = Math.max(0.05, Math.min(1.5, Math.min((rect.width - 40) / graphSize.w, (rect.height - 40) / graphSize.h)));
    setTransform({ k, x: (rect.width - graphSize.w * k) / 2, y: (rect.height - graphSize.h * k) / 2 });
  };
  fitViewRef.current = fitView;

  useEffect(() => {
    fitView();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [direction, isNarrow]);

  useEffect(() => {
    const svg = svgRef.current;
    if (!svg) return;
    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      const rect = svg.getBoundingClientRect();
      const cx = e.clientX - rect.left;
      const cy = e.clientY - rect.top;
      setTransform((t) => {
        const k = Math.min(4, Math.max(0.05, t.k * Math.exp(-e.deltaY * 0.0015)));
        const s = k / t.k;
        return { k, x: cx - (cx - t.x) * s, y: cy - (cy - t.y) * s };
      });
    };
    svg.addEventListener("wheel", onWheel, { passive: false });
    return () => svg.removeEventListener("wheel", onWheel);
  }, []);

  const centerOn = (id: string) => {
    const el = containerRef.current;
    const p = posOf(id);
    if (!el || !p) return;
    const rect = el.getBoundingClientRect();
    setTransform((t) => ({
      ...t,
      x: rect.width / 2 - (p.x + nodeW(id) / 2) * t.k,
      y: rect.height / 2 - (p.y + nodeH(id) / 2) * t.k,
    }));
  };

  const selectAndCenter = (id: string) => {
    setSelected(id);
    centerOn(id);
  };

  // ---- edge geometry -----------------------------------------------------------------
  const edgePath = (e: DAGLayoutEdge) => {
    if (direction === "horizontal") {
      const dx = Math.max(24, Math.abs(e.targetX - e.sourceX) * 0.45);
      return `M ${e.sourceX} ${e.sourceY} C ${e.sourceX + dx} ${e.sourceY} ${e.targetX - dx} ${e.targetY} ${e.targetX} ${e.targetY}`;
    }
    const dy = Math.max(24, Math.abs(e.targetY - e.sourceY) * 0.45);
    return `M ${e.sourceX} ${e.sourceY} C ${e.sourceX} ${e.sourceY + dy} ${e.targetX} ${e.targetY - dy} ${e.targetX} ${e.targetY}`;
  };

  const rectT = (hw: number, hh: number, ux: number, uy: number) =>
    Math.min(ux === 0 ? Infinity : hw / Math.abs(ux), uy === 0 ? Infinity : hh / Math.abs(uy));

  const freeEdgePath = (from: string, to: string) => {
    const a = posOf(from);
    const b = posOf(to);
    if (!a || !b) return "";
    const aw = nodeW(from);
    const bw = nodeW(to);
    const acx = a.x + aw / 2;
    const acy = a.y + 20;
    const bcx = b.x + bw / 2;
    const bcy = b.y + 20;
    let dx = bcx - acx;
    let dy = bcy - acy;
    const d = Math.hypot(dx, dy) || 1;
    dx /= d;
    dy /= d;
    const ta = rectT(aw / 2, 20, dx, dy);
    const tb = rectT(bw / 2, 20, dx, dy);
    return `M ${acx + dx * ta} ${acy + dy * ta} L ${bcx - dx * (tb + 3)} ${bcy - dy * (tb + 3)}`;
  };

  const hotEdges = new Set<string>();
  const focusId = selected ?? hovered;
  if (focusId) {
    for (const e of visibleEdges) {
      if (e.from === focusId || e.to === focusId) hotEdges.add(edgeKey(e.from, e.to));
    }
  }

  // ---- actions -------------------------------------------------------------------------
  const toggleCat = (catId: string) =>
    setHiddenCats((prev) => (prev.includes(catId) ? prev.filter((c) => c !== catId) : [...prev, catId]));

  const resetAll = () => {
    setHiddenCats([]);
    setQuery("");
    fitView();
  };

  const openInFile = () => {
    if (!selectedNode || selectedNode.line == null) return;
    dispatch({
      type: "openFile",
      path: GENERATED.sourcePath,
      selection: {
        startLineNumber: selectedNode.line,
        startColumn: 1,
        endLineNumber: selectedNode.line,
        endColumn: 1,
      },
    });
  };

  const jumpOptions = useMemo(
    () =>
      [...visibleNodes]
        .sort((a, b) => a.name.localeCompare(b.name))
        .map((n) => ({ value: n.id, label: `${n.id} — ${trunc(n.name, 28)}` })),
    [visibleNodes]
  );

  const chipList = (ids: string[]) => {
    const shown = ids.slice(0, 14);
    return (
      <Row gap={6} wrap>
        {shown.map((id) => {
          const n = nodeById.get(id);
          if (!n) return null;
          return (
            <span key={id} style={{ display: "inline-flex" }}>
              <Pill
                size="sm"
                title={n.name}
                onClick={() => selectAndCenter(id)}
                leadingContent={
                  <span style={{ width: 7, height: 7, borderRadius: 4, background: catColor(n.cat), display: "inline-block" }} />
                }
              >
                {n.id}
              </Pill>
            </span>
          );
        })}
        {ids.length > shown.length && (
          <Text size="small" tone="tertiary">
            +{ids.length - shown.length} more
          </Text>
        )}
      </Row>
    );
  };

  const generatedStamp = GENERATED.generatedAt
    ? GENERATED.generatedAt.slice(0, 16).replace("T", " ") + " UTC"
    : "";

  return (
    <div ref={rootRef} style={{ width: "100%" }}>
    <Stack gap={isNarrow ? 10 : 16} style={{ padding: isNarrow ? 12 : 24 }}>
      <Stack gap={6}>
        <H1>Benefuture concept graph</H1>
        <Text tone="secondary">
          {GENERATED.nodes.length} concepts · {GENERATED.edges.length} relationships parsed from {GENERATED.source}.
          Arrows point from each concept to the concepts it feeds; dashed edges close cycles.
          {generatedStamp ? ` Regenerated ${generatedStamp}.` : ""}
        </Text>
      </Stack>

      <Row gap={24} wrap>
        <Stat value={String(GENERATED.nodes.length)} label="Concepts" />
        <Stat value={String(GENERATED.edges.length)} label="Relationships" />
        <Stat value={String(GENERATED.categories.length)} label="Categories" />
        <Stat value={String(GENERATED.stats.axioms)} label="Anti-fragility axioms" />
      </Row>

      <Row gap={8} align="center" wrap>
        <TextInput value={query} onChange={setQuery} placeholder="Filter by name or symbol…" style={{ width: isNarrow ? "100%" : 220 }} />
        <Select
          value={selected ?? ""}
          onChange={(v) => selectAndCenter(v)}
          options={jumpOptions}
          placeholder="Jump to concept…"
          style={{ width: isNarrow ? "100%" : 220 }}
        />
        <Pill active={direction === "horizontal"} onClick={() => setDirection("horizontal")}>
          Left → right
        </Pill>
        <Pill active={direction === "vertical"} onClick={() => setDirection("vertical")}>
          Top → bottom
        </Pill>
        <Pill active={direction === "free"} onClick={() => setDirection("free")}>
          Free floating
        </Pill>
        <Button variant="secondary" onClick={fitView}>
          Fit view
        </Button>
        <Button variant="ghost" onClick={resetAll}>
          Reset
        </Button>
      </Row>

      <Row gap={6} wrap>
        {GENERATED.categories.map((cat) => (
          <span key={cat.id} style={{ display: "inline-flex" }}>
            <Pill
              active={!hiddenCats.includes(cat.id)}
              onClick={() => toggleCat(cat.id)}
              leadingContent={
                <span style={{ width: 8, height: 8, borderRadius: 4, background: catColor(cat.id), display: "inline-block" }} />
              }
            >
              {`${cat.label} ${cat.count}`}
            </Pill>
          </span>
        ))}
      </Row>

      <div
        style={{
          width: "100%",
          display: "flex",
          flexDirection: isNarrow ? "column" : "row",
          gap: 16,
          alignItems: isNarrow ? "stretch" : "flex-start",
        }}
      >
        <div
          ref={containerRef}
          style={{
            flex: 1,
            minWidth: 0,
            width: isNarrow ? "100%" : undefined,
            height: isNarrow ? Math.max(320, Math.round(pageWidth)) : 640,
            position: "relative",
            overflow: "hidden",
            border: `1px solid ${theme.stroke.tertiary}`,
            borderRadius: 10,
            background: theme.bg.chrome,
          }}
        >
          <svg
            ref={svgRef}
            width="100%"
            height="100%"
            style={{ display: "block", touchAction: "none" }}
            onPointerDown={(e: { clientX: number; clientY: number }) => {
              lastDragMoved.current = false;
              dragRef.current = { px: e.clientX, py: e.clientY, x: transform.x, y: transform.y, moved: false };
            }}
            onPointerMove={(e: { clientX: number; clientY: number }) => {
              const nd = nodeDragRef.current;
              if (nd) {
                const svg = svgRef.current;
                if (!svg) return;
                const rect = svg.getBoundingClientRect();
                nd.gx = (e.clientX - rect.left - transform.x) / transform.k;
                nd.gy = (e.clientY - rect.top - transform.y) / transform.k;
                nd.moved = true;
                reheat(0.25);
                return;
              }
              const d = dragRef.current;
              if (!d) return;
              const dx = e.clientX - d.px;
              const dy = e.clientY - d.py;
              if (Math.abs(dx) + Math.abs(dy) > 3) d.moved = true;
              setTransform((t) => ({ ...t, x: d.x + dx, y: d.y + dy }));
            }}
            onPointerUp={() => {
              lastDragMoved.current = Boolean(dragRef.current?.moved || nodeDragRef.current?.moved);
              if (nodeDragRef.current) reheat(0.35);
              dragRef.current = null;
              nodeDragRef.current = null;
            }}
            onPointerLeave={() => {
              lastDragMoved.current = Boolean(dragRef.current?.moved || nodeDragRef.current?.moved);
              if (nodeDragRef.current) reheat(0.35);
              dragRef.current = null;
              nodeDragRef.current = null;
            }}
          >
            <defs>
              <marker id="bf-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse" markerUnits="userSpaceOnUse">
                <path d="M 0 1 L 9 5 L 0 9 z" fill={theme.text.quaternary} />
              </marker>
              <marker id="bf-arrow-hot" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse" markerUnits="userSpaceOnUse">
                <path d="M 0 1 L 9 5 L 0 9 z" fill={theme.accent.primary} />
              </marker>
            </defs>
            <g transform={`translate(${transform.x},${transform.y}) scale(${transform.k})`}>
              <rect
                x={-8000}
                y={-8000}
                width={16000}
                height={16000}
                fill="transparent"
                onClick={() => {
                  if (!lastDragMoved.current) setSelected(null);
                }}
              />
              {(isFree
                ? visibleEdges.map((e) => ({ from: e.from, to: e.to, d: freeEdgePath(e.from, e.to), back: false }))
                : layout.edges.map((e) => ({ from: e.from, to: e.to, d: edgePath(e), back: Boolean(e.isBackEdge) }))
              ).map((e) => {
                const key = edgeKey(e.from, e.to);
                const isHot = hotEdges.has(key);
                const dimmed =
                  (neighborInfo && !neighborInfo.set.has(e.from) && !neighborInfo.set.has(e.to)) ||
                  (matchIds && !matchIds.has(e.from) && !matchIds.has(e.to));
                return (
                  <path
                    key={key}
                    d={e.d}
                    fill="none"
                    stroke={isHot ? theme.accent.primary : theme.stroke.primary}
                    strokeWidth={isHot ? 1.8 : 1}
                    strokeDasharray={e.back ? "5 4" : undefined}
                    opacity={dimmed ? 0.08 : isHot ? 0.95 : 0.55}
                    markerEnd={isHot ? "url(#bf-arrow-hot)" : "url(#bf-arrow)"}
                  />
                );
              })}
              {visibleNodes.map((n) => {
                const p = posOf(n.id);
                if (!p) return null;
                const w = nodeW(n.id);
                const h = nodeH(n.id);
                const color = catColor(n.cat);
                const isSel = selected === n.id;
                const isHovered = hovered === n.id;
                const dimmed =
                  (neighborInfo && !neighborInfo.set.has(n.id)) || (matchIds && !matchIds.has(n.id));
                const subtitle = n.name !== n.id ? trunc(n.name, 20) : n.axiom ? "§Af_Axioms" : n.isSet ? "§Sets" : "";
                return (
                  <g
                    key={n.id}
                    transform={`translate(${p.x},${p.y})`}
                    opacity={dimmed ? 0.18 : 1}
                    style={{ cursor: isFree ? "grab" : "pointer" }}
                    onPointerDown={
                      isFree
                        ? (e: { clientX: number; clientY: number; stopPropagation: () => void }) => {
                            e.stopPropagation();
                            const svg = svgRef.current;
                            if (!svg) return;
                            const rect = svg.getBoundingClientRect();
                            const gx = (e.clientX - rect.left - transform.x) / transform.k;
                            const gy = (e.clientY - rect.top - transform.y) / transform.k;
                            nodeDragRef.current = { id: n.id, dx: gx - p.x, dy: gy - p.y, gx, gy, moved: false };
                            lastDragMoved.current = false;
                            reheat(0.3);
                          }
                        : undefined
                    }
                    onClick={(e: { stopPropagation: () => void }) => {
                      e.stopPropagation();
                      if (!lastDragMoved.current) setSelected(isSel ? null : n.id);
                    }}
                    onMouseEnter={() => setHovered(n.id)}
                    onMouseLeave={() => setHovered((h) => (h === n.id ? null : h))}
                  >
                    <rect
                      width={w}
                      height={h}
                      rx={7}
                      fill={theme.bg.elevated}
                      stroke={isSel ? theme.accent.primary : isHovered ? theme.stroke.focused : theme.stroke.primary}
                      strokeWidth={isSel ? 2 : 1}
                    />
                    <rect width={4} height={h - 12} x={6} y={6} rx={2} fill={color} />
                    {isFree ? (
                      <>
                        <text x={16} y={17} fontSize={10.5} fontWeight={600} fill={theme.text.primary} fontFamily="inherit">
                          {n.name}
                        </text>
                        <text x={16} y={31} fontSize={8.5} fill={color} fontFamily="inherit">
                          {n.id}
                        </text>
                      </>
                    ) : (
                      <>
                        <text x={16} y={19} fontSize={11} fontWeight={700} fill={color} fontFamily="inherit">
                          {n.id}
                        </text>
                        <text x={16} y={34} fontSize={9.5} fill={theme.text.secondary} fontFamily="inherit">
                          {subtitle}
                        </text>
                      </>
                    )}
                  </g>
                );
              })}
            </g>
          </svg>
          <div
            style={{
              position: "absolute",
              left: 10,
              bottom: 8,
              fontSize: 11,
              color: theme.text.quaternary,
              pointerEvents: "none",
            }}
          >
            {visibleNodes.length} shown · drag to pan · scroll to zoom · click a node for details
            {isFree ? " · drag nodes to rearrange" : ""}
          </div>
        </div>

        {selectedNode && (
          <div style={isNarrow ? { width: "100%" } : { width: 300, flexShrink: 0 }}>
            <Card>
              <CardHeader
                trailing={
                  <Pill size="sm">
                    {catById.get(selectedNode.cat)?.label ?? selectedNode.cat}
                  </Pill>
                }
              >
                {selectedNode.name}
              </CardHeader>
              <CardBody>
                <Stack gap={12}>
                  <Row gap={6} wrap>
                    <Pill size="sm" active>
                      {selectedNode.id}
                    </Pill>
                    {selectedNode.subGoal && <Pill size="sm">Sub-Goal</Pill>}
                    {selectedNode.axiom && <Pill size="sm">§Af_Axioms</Pill>}
                    {selectedNode.isSet && <Pill size="sm">§Sets</Pill>}
                  </Row>
                  <Stack gap={4}>
                    <Text size="small" tone="tertiary">
                      Definition
                    </Text>
                    <div
                      style={{
                        fontFamily: "ui-monospace, monospace",
                        fontSize: 11.5,
                        lineHeight: 1.5,
                        color: theme.text.secondary,
                        background: theme.fill.tertiary,
                        borderRadius: 6,
                        padding: "8px 10px",
                        whiteSpace: "pre-wrap",
                        wordBreak: "break-word",
                      }}
                    >
                      {selectedNode.def || "Referenced concept — no explicit definition in the source."}
                    </div>
                  </Stack>
                  {neighborInfo && neighborInfo.dependsOn.length > 0 && (
                    <Stack gap={4}>
                      <Text size="small" tone="tertiary">
                        Depends on ({neighborInfo.dependsOn.length})
                      </Text>
                      {chipList(neighborInfo.dependsOn)}
                    </Stack>
                  )}
                  {neighborInfo && neighborInfo.feedsInto.length > 0 && (
                    <Stack gap={4}>
                      <Text size="small" tone="tertiary">
                        Feeds into ({neighborInfo.feedsInto.length})
                      </Text>
                      {chipList(neighborInfo.feedsInto)}
                    </Stack>
                  )}
                  {selectedNode.line != null && (
                    <Row>
                      <Button variant="ghost" onClick={openInFile}>
                        {`Open ${GENERATED.source}:${selectedNode.line}`}
                      </Button>
                    </Row>
                  )}
                </Stack>
              </CardBody>
            </Card>
          </div>
        )}
      </div>

      <Text size="small" tone="tertiary">
        Parsed from §Sets, §Defs, §Af_Axioms and §Txonmy by tools/bf-graph/build-graph.mjs. Edge direction:
        dependency → dependent. Full text: [benefuture.miraheze.org](https://benefuture.miraheze.org/)
      </Text>
    </Stack>
    </div>
  );
}
